// Stage 1 — normalize: one unicode form, one whitespace rule
function normalizeText(s) {
  return s
    .normalize('NFKC')                    // compatibility forms → canonical
    .replace(/[\u00A0\u2000-\u200B\u202F\u205F\u3000]/g, ' ') // exotic spaces
    .replace(/\s+/g, ' ')                 // collapse runs (incl. newlines)
    .trim();
}
// 'Müller' (2 encodings) → 1 string; 'a  b' → 'a b'. NFKC also folds ﬁ→fi.

