// Stage 3 — standardize dates (explicit day-first policy, verified on samples)
function standardizeDate(raw) {
  const m = raw.trim().match(/^(\d{1,2})[/.](\d{1,2})[/.](\d{4})$/);
  if (!m) return { ok: false, reason: 'unrecognized date shape: ' + raw };
  const [, d, mo, y] = m; // POLICY: day-first (corpus convention, sampled)
  const iso = `${y}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}`;
  const dt = new Date(iso + 'T00:00:00Z');
  if (Number.isNaN(dt.getTime())) return { ok: false, reason: 'impossible date: ' + raw };
  return { ok: true, value: iso };
}
// standardizeDate('6/10/2026') -> { ok: true, value: '2026-10-06' }
// standardizeDate('13/13/2026') -> { ok: false, ... } (quarantine, not crash)

